@Service
public class OrderService {
    @Value("${app.name}")
    private String appName;  // Injects "OrderService"

    @Value("${app.max-orders}")
    private int maxOrders;   // Injects 100

    public void processOrder(Order order) {
        System.out.println("Processing in " + appName);
        // Use maxOrders for business logic
    }
}

// Better approach for grouped properties:
@ConfigurationProperties(prefix = "app")
public record AppConfig(String name, int maxOrders) {}

@RestController
public class OrderController {
    private final AppConfig config;  // Spring injects this automatically

    public OrderController(AppConfig config) {
        this.config = config;
    }
}

