@Service
@Profile("dev")  // Only active when 'dev' profile is on
public class MockPaymentService implements PaymentService {
    public boolean processPayment(Order order) {
        return true;  // Always succeeds in dev
    }
}

@Service
@Profile("prod")  // Only active in production
public class StripePaymentService implements PaymentService {
    public boolean processPayment(Order order) {
        // Real payment gateway integration
        return stripeClient.charge(order.getTotal());
    }
}

// Using @Value for individual properties
@Service
public class OrderService {
    @Value("${app.max-orders-per-user}")
    private int maxOrdersPerUser; // reads app.max-orders-per-user from properties

    @Value("${app.discount.enabled:false}") // default value after colon
    private boolean discountEnabled;
}

// Using @ConfigurationProperties for grouped properties
@ConfigurationProperties(prefix = "app.payment")
@Component
public class PaymentConfig {
    private String apiKey;
    private String gatewayUrl;
    private int timeoutSeconds;
    private boolean retryEnabled;

    // Getters and setters (or use record for immutability)
}

// application.properties (lowest precedence)
app.api-key=dev-key-12345
server.port=8080

// application-prod.properties (overrides base)
app.api-key=prod-key-should-not-be-here
server.port=9090

// Environment variable (highest precedence)
// export APP_API_KEY=secret-prod-key-from-vault
// export SERVER_PORT=8443

// JVM system property (higher than files)
// java -Dserver.port=8081 -jar myapp.jar

@RestController
public class ConfigController {
    @Value("${app.api-key}")
    private String apiKey;  // Gets value based on precedence

    @Value("${server.port}")
    private int serverPort;

    @GetMapping("/config")
    public Map<String, String> showConfig() {
        // In production with env vars set:
        // apiKey = "secret-prod-key-from-vault" (from env)
        // serverPort = 8443 (from env)

        // Locally with no env vars:
        // apiKey = "dev-key-12345" (from file)
        // serverPort = 8080 (from file)

        return Map.of("apiKey", apiKey, "port", String.valueOf(serverPort));
    }
}

