// src/test/resources/application-test.properties
server.port=0  // Random port for tests

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
public class OrderControllerIntegrationTest {

    @LocalServerPort  // Injects the actual random port chosen
    private int port;

    @Autowired
    private TestRestTemplate restTemplate;  // Pre-configured for the random port

    @Test
    void shouldCreateOrder() {
        var order = new Order(null, "Laptop", 999.99);

        var response = restTemplate.postForEntity(
            "http://localhost:" + port + "/api/orders",
            order,
            Order.class
        );

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.CREATED);
    }
}

// Programmatically retrieve port in application code
@Component
public class ServerPortLogger {
    @Value("${local.server.port}")
    private int actualPort;  // Available after server starts

    @EventListener(ApplicationReadyEvent.class)
    public void logPort() {
        System.out.println("Server started on port: " + actualPort);
    }
}

// src/main/resources/application-dev.properties
spring.jpa.hibernate.ddl-auto=create-drop
spring.jpa.show-sql=true
spring.h2.console.enabled=true

// src/main/resources/application-prod.properties
spring.jpa.hibernate.ddl-auto=validate
spring.jpa.show-sql=false

// Entity class that Hibernate uses to generate schema
@Entity
public class Order {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false, length = 100)
    private String customerName;

    @Column(nullable = false)
    private BigDecimal totalAmount;

    @Column(nullable = false)
    private LocalDateTime createdAt;

    // With ddl-auto=create, Hibernate generates:
    // CREATE TABLE order (
    //   id BIGINT AUTO_INCREMENT PRIMARY KEY,
    //   customer_name VARCHAR(100) NOT NULL,
    //   total_amount DECIMAL(19,2) NOT NULL,
    //   created_at TIMESTAMP NOT NULL
    // );

    // If you change @Column(length=100) to @Column(length=50)
    // with ddl-auto=update, Hibernate issues:
    // ALTER TABLE order MODIFY customer_name VARCHAR(50);
    // (This can truncate existing data!)
}
